mapper.select:
SELECT count(*) FROM entities e WHERE e.kb_id = #{kbId}
  AND NOT EXISTS (SELECT 1 FROM entity_merges m
                  WHERE m.source_id = e.id AND m.reverted_at IS NULL)

SELECT * FROM ( SELECT ev.id AS fact_id, ev.at, ev.kind, ev.direction, COALESCE(r.label, fact_surface_predicate(ev.id)) AS predicate_label, o.canonical_name AS other_name, ev.object_value, ev.valid_from, ev.valid_from_precision, ev.valid_to, ev.valid_to_precision, ev.confidence, act.actor_name, act.action, src.document_id, src.filename, src.quote, NULL::text AS from_type_label, NULL::text AS to_type_label FROM ev LEFT JOIN relation_types r ON r.id = ev.predicate_id LEFT JOIN entities o ON o.id = ev.other_id LEFT JOIN LATERAL ( SELECT u.display_name AS actor_name, a.action FROM audit_events a LEFT JOIN users u ON u.id = a.actor_id WHERE a.kb_id = #{kbId}
AND ev.kind <> 'asserted' AND a.action = ANY(CASE ev.kind WHEN 'corrected' THEN ARRAY['fact.close', 'conflict.close_old', 'ontology.predicate_adopted', 'fact.time_corrected'] WHEN 'merged' THEN ARRAY['ontology.predicate_adopted'] ELSE ARRAY['fact.reject', 'conflict.reject_new', 'ontology.adoption_reverted'] END) AND (a.target_id = COALESCE(ev.supersedes, ev.id) OR a.target_id IN (SELECT c.id FROM fact_conflicts c WHERE c.old_fact_id = COALESCE(ev.supersedes, ev.id) OR c.new_fact_id = ev.id) OR (a.action IN ('ontology.predicate_adopted', 'ontology.adoption_reverted') AND EXISTS (SELECT 1 FROM fact_adoptions fa WHERE fa.predicate_id = a.target_id AND (fa.new_fact_id = ev.id OR fa.old_fact_id = ev.id)))) ORDER BY a.created_at DESC LIMIT 1 ) act ON true LEFT JOIN LATERAL ( SELECT d.id AS document_id, d.filename, fe.quote FROM fact_evidence fe JOIN chunks c ON c.id = fe.chunk_id JOIN documents d ON d.id = c.document_id WHERE fe.fact_id = ev.id ORDER BY fe.doc_version DESC NULLS LAST LIMIT 1 ) src ON true UNION ALL SELECT NULL::uuid, rt.at, rt.kind, NULL::text, NULL::text, NULL::text, NULL::jsonb, NULL::timestamptz, NULL::text, NULL::timestamptz, NULL::text, NULL::real, u.display_name, NULL::text, NULL::uuid, NULL::text, NULL::text, rt.from_type_label, rt.to_type_label FROM rt LEFT JOIN users u ON u.id = rt.actor_id UNION ALL
SELECT NULL::uuid, mg.at, mg.kind, NULL::text, NULL::text, o.canonical_name, NULL::jsonb, NULL::timestamptz, NULL::text, NULL::timestamptz, NULL::text, NULL::real, u.display_name, NULL::text, NULL::uuid, NULL::text, NULL::text, NULL::text, NULL::text FROM mg LEFT JOIN entities o ON o.id = mg.other_id LEFT JOIN users u ON u.id = mg.actor_id ) x
ORDER BY x.at DESC, x.fact_id, x.kind, x::text LIMIT #{limit} OFFSET #{offset}
